diff.code:
function bench(fn, input) {
  const t0 = Date.now();
  let result;
  for (let i = 0; i < 1e8; i++) {
    result = fn(input);     // one giant timed loop, no warm-up
  }
  const ms = Date.now() - t0;
  return { nsPerCall: ms * 1e6 / 1e8, result };
}

function compare(a, b, input) {
  const ra = bench(a, input);
  const rb = bench(b, input);
  return ra.nsPerCall < rb.nsPerCall ? 'a faster' : 'b faster';
}
